package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"
)

func main() {
	var sysin interface{}
	b, err := io.ReadAll(os.Stdin)
	if err != nil {
		panic(err)
	}
	if err := json.Unmarshal(b, &sysin); err != nil {
		panic(err)
	}

	cmd := ""
	if sysin != nil {
		cmd = sysin.(string)
	}

	cmdArgs := strings.Fields(cmd)
	composePaths := []string{}
	for i := 0; i < len(cmdArgs); i++ {
		if cmdArgs[i] == "-f" && i+1 < len(cmdArgs) {
			composePaths = append(composePaths, cmdArgs[i+1])
		}
	}

	var result interface{} = composePaths

	out, err := json.Marshal(result)
	if err != nil {
		panic(err)
	}
	fmt.Println(string(out))
}

import sys
import json

sysin = json.loads(sys.stdin.read() or "null")

stops = {}
for beat, stop in sysin:
    if beat in stops:
        stops[beat] += stop
    stops[beat] = stop

result = stops

print(json.dumps(result, ensure_ascii=False))
